Rules.InvariantScript:
If(

    IsBlank(txtFirstName.Text) ||
    IsBlank(txtLastName.Text) ||
    IsBlank(txtDD.Text) ||
    IsBlank(txtMM.Text) ||
    IsBlank(txtYYYY.Text) ||
    IsBlank(txtNumber.Text) ||
    IsBlank(txtEmail.Text) ||
    IsBlank(txtCity.Text),

    Notify(
        "Please fill in all required fields",
        NotificationType.Error
    ),

    Reset(txtFirstName);
    Reset(txtLastName);

    Reset(txtDD);
    Reset(txtMM);
    Reset(txtYYYY);

    Reset(txtNumber);
    Reset(txtEmail);
    Reset(txtCity);
    

    Reset(txtIntroduction);

    Navigate('success page submission')

)
